    seen = set()
    fill_by_side = {5: 8, 7: 4, 9: 3}

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
