                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 2 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in component)
            r1 = max(y for y, x in component)
            c0 = min(x for y, x in component)
            c1 = max(x for y, x in component)
            height, width = r1 - r0 + 1, c1 - c0 + 1

            if height != width or width not in fill_by_side:
                continue

            if all(grid[y][x] == 2
                   for y in range(r0, r1 + 1)
                   for x in range(c0, c1 + 1)
                   if y in (r0, r1) or x in (c0, c1)):
